---RefreshDropDetails 刷新关卡掉落详情
---@param commonRewards table[] 常规掉落
---@param rareRewards table[] 稀有掉落
function QuestDropDetailDialog:RefreshDropDetails(commonRewards, rareRewards)
	if not isNull(commonRewards) then
		self.commonRewards = commonRewards
		GameUtils.ReloadData(self.CommonDropListView, table.count(commonRewards))
	end

	if not isNull(rareRewards) then
		self.rareRewards = rareRewards
		GameUtils.ReloadData(self.RareDropListView, table.count(rareRewards))
	end
end

---OnGetCommonRewardsItemByIndex 常规掉落列表刷新刷新回调
---@param listView SuperScrollView.LoopListView2 @ 列表对象
---@param index integer @ c#中的index
---@return SuperScrollView.LoopListViewItem2
function QuestDropDetailDialog:OnGetCommonRewardsItemByIndex(listView, index)
	-- 创建cell
	local cell = listView:NewListViewItem(GoodsCellPrefabName)

	if not KTool.IsNull(cell) then

		-- cell绑定的脚本
		local cellViewMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)

		if not KTool.IsNull(cellViewMB) then

			if not cell.IsInitHandlerCalled then
				cell.IsInitHandlerCalled = true
				-- 设置道具icon的点击回调
				UIEventProxy.Create(cell.gameObject).onPointerClick = Bind(self, self.OnGridCellClickAction)
			end

			local goodsId = checkInt(self.commonRewards[index])
			cellViewMB:AddString("id", checkString(goodsId))
			cellViewMB.Env:Reload({
				goodsId = goodsId,
				isShowNo = false
			})

		end

	end

	return cell

end

---OnGetCommonRewardsItemByIndex 稀有掉落列表刷新刷新回调
---@param listView SuperScrollView.LoopListView2 @ 列表对象
---@param index integer @ c#中的index
function QuestDropDetailDialog:OnGetRareRewardsItemByIndex(listView, index)
	-- 创建cell
	local cell = listView:NewListViewItem(GoodsCellPrefabName)

	if not KTool.IsNull(cell) then

		-- cell绑定的脚本
		local cellViewMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)

		if not KTool.IsNull(cellViewMB) then

			if not cell.IsInitHandlerCalled then
				cell.IsInitHandlerCalled = true
				-- 设置道具icon的点击回调
				UIEventProxy.Create(cell.gameObject).onPointerClick = Bind(self, self.OnGridCellClickAction)
			end

			local goodsId = checkInt(self.rareRewards[index])
			cellViewMB:AddString("id", checkString(goodsId))
			cellViewMB.Env:Reload({
				goodsId = goodsId,
				isShowNo = false
			})

		end

	end

	return cell
end

function QuestDropDetailDialog:OnGridCellClickAction(data)
	local go = data.selectedObject
	---@type Engine.Modules.LuaBehaviour
	local goodNodeMB = GetLuaBehaviour(go, GoodsNodeMBPath)
	local id = checkNumber(goodNodeMB:GetString("id"))
	GameUtils.ShowCommonGoodsTipsBoard(go, id, false)
end

